// --- 3D Circular Ring Buffer Rendering ---
function renderCircularBuffer() {
  const ring = document.getElementById('circular-ring');
  const countHub = document.getElementById('circular-hub-count');
  const readout = document.getElementById('circular-pointer-readout');

  countHub.textContent = `${engine.circularSize} / ${engine.circularCap}`;
  readout.textContent = `F: [${engine.circularFront}] | R: [${engine.circularRear}]`;

  ring.innerHTML = '';
  const total = engine.circularCap;
  const radius = 95; // Radius in px

  for (let i = 0; i < total; i++) {
    const angle = (i * 2 * Math.PI) / total - Math.PI / 2;
    const x = Math.round(radius * Math.cos(angle) + 110);
    const y = Math.round(radius * Math.sin(angle) + 110);

    const isOccupied = engine.circularQueue[i] !== null;
    const isFront = i === engine.circularFront && engine.circularSize > 0;
    const isRear = i === engine.circularRear;

    const slotEl = document.createElement('div');
    slotEl.className = `circular-slot ${isOccupied ? 'occupied' : ''} ${isFront ? 'is-front' : ''} ${isRear ? 'is-rear' : ''}`;
    slotEl.style.left = `${x}px`;
    slotEl.style.top = `${y}px`;

    const passenger = engine.circularQueue[i];
    slotEl.innerHTML = `
      <div class="font-bold">[${i}]</div>
      <div class="text-[9px] truncate max-w-[40px]">${passenger ? passenger.name.split(' ')[0] : 'EMPTY'}</div>
    `;
    slotEl.title = passenger ? `Slot ${i}: ${passenger.name} (${passenger.pickup}->${passenger.drop})` : `Slot ${i}: Available`;
    ring.appendChild(slotEl);
  }
}

