// --- Binary Search Tree (BST) Canvas Visualization ---
function renderBSTCanvas() {
  const canvas = document.getElementById('bst-canvas');
  const ctx = canvas.getContext('2d');
  const traversalLabel = document.getElementById('bst-traversal-label');

  const inOrderList = engine.getBSTInOrder();
  traversalLabel.textContent = `In-Order: [${inOrderList.join(', ')}]`;

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  if (!engine.bstRoot) {
    ctx.fillStyle = '#64748B';
    ctx.font = '11px "JetBrains Mono"';
    ctx.textAlign = 'center';
    ctx.fillText('BST Root is NULL. Match rides to view tree.', canvas.width / 2, canvas.height / 2);
    return;
  }

  function drawNode(node, x, y, offsetX) {
    if (!node) return;

    // Draw branch lines to children
    if (node.left) {
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x - offsetX, y + 42);
      ctx.strokeStyle = 'rgba(0, 243, 255, 0.4)';
      ctx.lineWidth = 1.5;
      ctx.stroke();
      drawNode(node.left, x - offsetX, y + 42, offsetX / 1.9);
    }

    if (node.right) {
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + offsetX, y + 42);
      ctx.strokeStyle = 'rgba(0, 243, 255, 0.4)';
      ctx.lineWidth = 1.5;
      ctx.stroke();
      drawNode(node.right, x + offsetX, y + 42, offsetX / 1.9);
    }

    // Node Circle
    ctx.beginPath();
    ctx.arc(x, y, 14, 0, Math.PI * 2);
    ctx.fillStyle = '#0F172A';
    ctx.strokeStyle = '#00F3FF';
    ctx.lineWidth = 2;
    ctx.shadowColor = '#00F3FF';
    ctx.shadowBlur = 8;
    ctx.fill();
    ctx.stroke();

    // Reset shadow
    ctx.shadowBlur = 0;

    // Node Text
    ctx.fillStyle = '#FFFFFF';
    ctx.font = 'bold 9px "JetBrains Mono"';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(`${node.rideId}`, x, y);
  }

  drawNode(engine.bstRoot, canvas.width / 2, 28, 90);
}

