// ==========================================
// 4. 3D ANTI-GRAVITY TILT CONTROLLER
// ==========================================
function bindTiltElements() {
  const cards = document.querySelectorAll('[data-tilt]');
  cards.forEach(card => {
    if (card._tiltBound) return;
    card._tiltBound = true;

    card.addEventListener('mousemove', (e) => {
      const rect = card.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const centerX = rect.width / 2;
      const centerY = rect.height / 2;

      // Subtle tilt angles (-10 to 10 deg)
      const rotateX = ((centerY - y) / centerY) * 9;
      const rotateY = ((x - centerX) / centerX) * 9;

      // Z-lift anti-gravity vector
      card.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) translateZ(12px)`;
    });

    card.addEventListener('mouseleave', () => {
      card.style.transform = 'perspective(1000px) rotateX(0deg) rotateY(0deg) translateZ(0px)';
    });
  });
}

